SET SESSION TRANSACTION READ ONLY;
START TRANSACTION READ ONLY;
SELECT 'product_variant_packaging_links' t,COUNT(*) n FROM product_variant_packaging_links UNION ALL SELECT 'product_documents',COUNT(*) FROM product_documents UNION ALL SELECT 'product_asset_machine_tier_links',COUNT(*) FROM product_asset_machine_tier_links UNION ALL SELECT 'packaging_assets',COUNT(*) FROM packaging_assets UNION ALL SELECT 'mold_variant_links',COUNT(*) FROM mold_variant_links UNION ALL SELECT 'finished_goods_lots',COUNT(*) FROM finished_goods_lots UNION ALL SELECT 'sales_products',COUNT(*) FROM sales_products UNION ALL SELECT 'video_user_favorites',COUNT(*) FROM video_user_favorites UNION ALL SELECT 'video_recent_views',COUNT(*) FROM video_recent_views UNION ALL SELECT 'video_collection_items',COUNT(*) FROM video_collection_items;
SELECT 'assets_variant' t,COUNT(*) n FROM product_assets WHERE variant_id IS NOT NULL AND deleted_at IS NULL UNION ALL SELECT 'assets_tier',COUNT(*) FROM product_assets WHERE machine_tier_id IS NOT NULL AND deleted_at IS NULL UNION ALL SELECT 'assets_website',COUNT(*) FROM product_assets WHERE website_visible=1 AND deleted_at IS NULL UNION ALL SELECT 'products_website',COUNT(*) FROM product_models WHERE website_enabled=1 AND deleted_at IS NULL UNION ALL SELECT 'molds_website',COUNT(*) FROM packaging_molds WHERE website_enabled=1 AND deleted_at IS NULL;
SELECT 'tier_fg_lots' t,COUNT(*) n FROM finished_goods_lots WHERE product_machine_tier_id IS NOT NULL UNION ALL SELECT 'model_fg_lots',COUNT(*) FROM finished_goods_lots WHERE product_model_id IS NOT NULL UNION ALL SELECT 'model_sales_products',COUNT(*) FROM sales_products WHERE product_model_id IS NOT NULL;
SELECT 'variant_packaging_orphan' t,COUNT(*) n FROM product_variant_packaging_links l LEFT JOIN product_variants v ON v.id=l.product_variant_id LEFT JOIN packaging_variants p ON p.id=l.packaging_variant_id WHERE v.id IS NULL OR p.id IS NULL UNION ALL SELECT 'variant_packaging_deleted_target',COUNT(*) FROM product_variant_packaging_links l JOIN product_variants v ON v.id=l.product_variant_id JOIN packaging_variants p ON p.id=l.packaging_variant_id WHERE v.deleted_at IS NOT NULL OR p.deleted_at IS NOT NULL UNION ALL SELECT 'mold_variant_orphan',COUNT(*) FROM mold_variant_links l LEFT JOIN packaging_molds m ON m.id=l.mold_id LEFT JOIN packaging_variants p ON p.id=l.variant_id WHERE m.id IS NULL OR p.id IS NULL UNION ALL SELECT 'mold_variant_deleted_target',COUNT(*) FROM mold_variant_links l JOIN packaging_molds m ON m.id=l.mold_id JOIN packaging_variants p ON p.id=l.variant_id WHERE l.deleted_at IS NULL AND (m.deleted_at IS NOT NULL OR p.deleted_at IS NOT NULL);
COMMIT;
